Lemma Forall_app_2 {A} (P : A -> Prop) (l1 l2 : list A) : Forall P l1 -> Forall P l2 -> Forall P (l1 ++ l2).
Proof. intros K1 K2. apply Forall_app. split; assumption. Qed.

